#include "kopruq/solvers/LinearStaticSolver.hpp"
#include <algorithm>
#include <chrono>
#include <iostream>
#include <vector>
int main(){using C=std::chrono::steady_clock;for(int n:{100,1000,10000}){kopruq::Model m;m.materials={{1,210e6,.3}};m.sections={{1,.3,.02,.04,.01}};for(int i=0;i<=n;++i)m.nodes.push_back({(kopruq::Id)i+1,double(i),0,0});for(int i=0;i<n;++i)m.beams.push_back({(kopruq::Id)i+1,(kopruq::Id)i+1,(kopruq::Id)i+2,1,1,{0,1,0}});kopruq::DofManager dm(m);std::map<kopruq::Id,std::array<bool,6>> rs;for(const auto&x:m.nodes)rs[x.id]={false,false,false,false,false,false};rs[1]={true,true,true,true,true,true};auto b=kopruq::MatrixAssembler::classify(dm,rs);std::vector<kopruq::NodalLoad> loads={{(kopruq::Id)n+1,(Eigen::Matrix<double,6,1>()<<1,1,1,0,0,0).finished()}};auto fullF=kopruq::LinearStaticSolver::assembleLoads(dm,loads);std::vector<double>a,r,s,f,q,rec;Eigen::SparseMatrix<double>K,Kf;Eigen::VectorXd Ff,u,U;Eigen::SimplicialLDLT<Eigen::SparseMatrix<double>>ldlt;auto run=[&](){auto t=C::now();K=kopruq::MatrixAssembler::assemble(m);a.push_back(std::chrono::duration<double,std::milli>(C::now()-t).count());t=C::now();Kf=kopruq::LinearStaticSolver::reduceKff(K,b.free);Ff.resize((int)b.free.size());for(size_t i=0;i<b.free.size();++i)Ff((int)i)=fullF((int)b.free[i]);r.push_back(std::chrono::duration<double,std::milli>(C::now()-t).count());t=C::now();ldlt.analyzePattern(Kf);s.push_back(std::chrono::duration<double,std::milli>(C::now()-t).count());t=C::now();ldlt.factorize(Kf);f.push_back(std::chrono::duration<double,std::milli>(C::now()-t).count());t=C::now();u=ldlt.solve(Ff);q.push_back(std::chrono::duration<double,std::milli>(C::now()-t).count());U=Eigen::VectorXd::Zero((Eigen::Index)dm.dof_count());for(size_t i=0;i<b.free.size();++i)U((Eigen::Index)b.free[i])=u((Eigen::Index)i);t=C::now();auto results=kopruq::LinearStaticSolver::recover(m,rs,loads,U);rec.push_back(std::chrono::duration<double,std::milli>(C::now()-t).count());(void)results;};run();a.clear();r.clear();s.clear();f.clear();q.clear();rec.clear();for(int i=0;i<5;++i)run();auto med=[](auto v){std::sort(v.begin(),v.end());return v[v.size()/2];};double absres=(Kf*u-Ff).norm(),normres=absres/(Kf.norm()*u.norm()+Ff.norm()+1e-300);std::cout<<n<<" elements nodes="<<m.nodes.size()<<" total_dofs="<<dm.dof_count()<<" free_dofs="<<b.free.size()<<" nnzK="<<K.nonZeros()<<" nnzKff="<<Kf.nonZeros()<<" assembly="<<med(a)<<" reduction="<<med(r)<<" symbolic="<<med(s)<<" numeric="<<med(f)<<" solve="<<med(q)<<" recovery="<<med(rec)<<" abs_residual="<<absres<<" normalized_residual="<<normres<<" memory_bytes="<<(K.nonZeros()+Kf.nonZeros())*24<<"\n";}}
